// --- CÓDIGO CORRIGIDO PARA FORMATAR CARRINHO COM O ÍNDICE DO PRÓPRIO ITEM ---

// 1. Pega os dados de entrada
const sessao = $items("Start")[0].json;
const carrinho = sessao.carrinho_json || [];

// 2. Garante que os dados estão no formato correto
let carrinhoArray = [];
if (Array.isArray(carrinho)) {
carrinhoArray = carrinho;
} else if (typeof carrinho === 'string') {
try {
carrinhoArray = JSON.parse(carrinho);
} catch (e) {
carrinhoArray = [];
}
}

// 3. Validação
if (carrinhoArray.length === 0) {
return [{
json: {
carrinho_formatado_com_indice: "Seu carrinho está vazio.",
total_valor: "0.00"
}
}];
}

// 4. Prepara as variáveis fora do loop
let totalGeral = 0;
let carrinhoTextoFormatado = ""; // Renomeado para clareza

// 5. Loop CORRETO: Percorre o CARRINHO do cliente.
for (const itemNoCarrinho of carrinhoArray) {
const subtotal = (itemNoCarrinho.qtd || 0) * (itemNoCarrinho.precoUnitario || 0);
totalGeral += subtotal; // Acumula o valor total

const precoUnitarioFormatado = (itemNoCarrinho.precoUnitario || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }); const subtotalFormatado = subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

// --- CORREÇÃO --- // Pega o índice diretamente do item do carrinho, como você pediu. // Assume que a propriedade se chama 'Indice'.
const indice = itemNoCarrinho.indice || "?"; // --- FIM DA CORREÇÃO ---

// Monta a string no formato que você pediu.
carrinhoTextoFormatado += `*${indice})* `; 
  if (itemNoCarrinho.nome.toLowerCase().includes('combo')) {
    carrinhoTextoFormatado += `📦 ${itemNoCarrinho.nome.trim()}\n\n`;
  } else {
    carrinhoTextoFormatado += `🍫 ${itemNoCarrinho.nome.trim()}\n\n`;
  }
carrinhoTextoFormatado += `*Quantidade:* ${itemNoCarrinho.qtd}\n`; 
carrinhoTextoFormatado += `*Preço:* ${precoUnitarioFormatado} *(${subtotalFormatado})*\n`;

  // 👉 NOVO TRECHO — ITENS INTERNOS DO COMBO
  if (itemNoCarrinho.itens_internos && itemNoCarrinho.itens_internos.length > 0) {
    carrinhoTextoFormatado += `*Itens do Combo:*\n`;

    itemNoCarrinho.itens_internos.forEach(subItem => {
      carrinhoTextoFormatado += `${subItem.qtd}x ${subItem.nome}\n`;
    });

    carrinhoTextoFormatado += `\n\n`;
  }

  carrinhoTextoFormatado += `----------------------------------------------------------\n\n`;

}

// 6. Trata o caso de o carrinho estar vazio (embora já validado no início, é uma boa prática).
if (carrinhoTextoFormatado === "") {
carrinhoTextoFormatado = "Seu carrinho está vazio.";
}

// 7. Retorna o texto formatado e o total.
return [{
json: {
carrinho_formatado_com_indice: carrinhoTextoFormatado,
}
}];

const endereco = $items("busca_carrinho_atual")[0].json;
const pedido = $items("'Código Novo para \'Formatar Carrinho Final\'")[0].json

let verifica_endereco = `_*👸🏾 Kakaw - TheLordTrufas.*_\n\n`;
verifica_endereco += `_*${endereco.primeiro_nome}*_\n`;
verifica_endereco += `aqui está seu pedido:\n\n`;
verifica_endereco += `${pedido.mensagemResposta}`;
verifica_endereco += `----------------------------------------------------------\n\n`;
verifica_endereco += `Agora para seguirmos,\nconfirme seu endereço: 🗺️\n\n`;
verifica_endereco += `*📍→ RUA/Nº:*\n\n`;
verifica_endereco += `${endereco.endereco}\n\n`;
verifica_endereco += `*📍→ BAIRRO:*\n\n`;
verifica_endereco += `${endereco.bairro}\n\n`;
verifica_endereco += `*📍→ CEP:*\n\n`;
verifica_endereco += `${endereco.CEP.slice(0,5) + '-' + endereco.CEP.slice(5)}\n`;
if (!endereco.complemento) {
verifica_endereco += `\u200B`
} else {
verifica_endereco += `\n*📍→ COMPLEMENTO:*\n\n`;
verifica_endereco += `\n${endereco.complemento}\n\u200B`;
}

// Prepara a mensagem para ser enviada e o SQL para atualizar o estado.
$json.envia_endereco = verifica_endereco;
$json.Jid = endereco.jid;
$json.telefone_real = endereco.telefone_real;

return $json;

